// A bounded arithmetic parser. Formulas never execute JavaScript.
window.MathFormula={compile(source){
if(typeof source!=='string'||source.length>200)throw Error('Формула должна содержать от 1 до 200 символов.');
let s=source.toLowerCase().trim().replace(/^y\s*=/,'').replaceAll('²','^2').replaceAll('³','^3').replaceAll('π','pi').replace(/[×·]/g,'*').replace(/[÷:]/g,'/').replaceAll('−','-').replace(/(\d),(\d)/g,'$1.$2');
const ts=[];let i=0;while(i<s.length){if(/\s/.test(s[i])){i++;continue}const rest=s.slice(i),n=rest.match(/^(?:\d+(?:\.\d*)?|\.\d+)/),id=rest.match(/^[a-z]+/);if(n){ts.push({type:'number',value:Number(n[0])});i+=n[0].length}else if(id){ts.push({type:'id',value:id[0]});i+=id[0].length}else if('+-*/^()'.includes(s[i]))ts.push({type:s[i++ ]});else throw Error(`Неизвестный символ «${s[i]}». Используй x, числа и математические операции.`);if(ts.length>160)throw Error('Слишком сложная формула. Попробуй записать её короче.')}
const funcs={sin:Math.sin,cos:Math.cos,tan:Math.tan,sqrt:Math.sqrt,abs:Math.abs,ln:Math.log,log:Math.log10,exp:Math.exp,asin:Math.asin,acos:Math.acos,atan:Math.atan,floor:Math.floor,ceil:Math.ceil};let pos=0,depth=0;const at=()=>ts[pos]?.type,accept=t=>at()===t?(pos++,true):false;const node=(op,a,b)=>({op,a,b});
function atom(){if(++depth>60)throw Error('Слишком много вложенных скобок.');let result;const t=ts[pos];if(accept('number'))result=node('constant',t.value);else if(accept('id')){if(t.value==='x')result=node('x');else if(t.value==='pi'||t.value==='e')result=node('constant',t.value==='pi'?Math.PI:Math.E);else if(funcs[t.value]){if(!accept('('))throw Error(`После ${t.value} нужны скобки: ${t.value}(x).`);const a=sum();if(!accept(')'))throw Error('Не хватает закрывающей скобки.');result=node(t.value,a)}else throw Error(`Неизвестное имя «${t.value}». Переменная должна называться x.`)}else if(accept('(')){result=sum();if(!accept(')'))throw Error('Не хватает закрывающей скобки.')}else throw Error('Здесь ожидается число, x или выражение в скобках.');depth--;return result}
function power(){let a=atom();if(accept('^'))a=node('^',a,unary());return a}function unary(){if(accept('+'))return unary();if(accept('-'))return node('neg',unary());return power()}function product(){let a=unary();while(true){if(accept('*'))a=node('*',a,unary());else if(accept('/'))a=node('/',a,unary());else if(['number','id','('].includes(at()))a=node('*',a,unary());else break}return a}function sum(){let a=product();while(at()==='+'||at()==='-'){const op=ts[pos++].type;a=node(op,a,product())}return a}
if(!ts.length)throw Error('Введи формулу, например x^2 − 3.');const tree=sum();if(pos!==ts.length)throw Error('Проверь лишние скобки и знаки операций.');function evaluate(n,x){if(n.op==='constant')return n.a;if(n.op==='x')return x;const a=evaluate(n.a,x);if(n.op==='neg')return -a;if(funcs[n.op])return funcs[n.op](a);const b=evaluate(n.b,x);switch(n.op){case '+':return a+b;case '-':return a-b;case '*':return a*b;case '/':return a/b;case '^':return a**b}}return x=>evaluate(tree,x)
}};
